// Recursive function to generate Fibonacci sequence
unsigned long long fibonacci(int n, int a, int b) {
    if (n == 0) {
        return 0;
    }
    return fibonacci(n - 1, b, a + b);
}

int main() {
    std::string input;
    int a, b, n;

    // Prompt user for first two sequence elements
    std::cout << "Enter the first Fibonacci number: ";
    std::getline(std::cin, input);
    std::stringstream ss(input);
    ss >> a;
    if (!ss || cin.fail() || a < 0) {
        throw std::invalid_argument("First Fibonacci number must be a non-negative integer.");
    }

    std::cout << "Enter the second Fibonacci number: ";
    std::getline(std::cin, input);
    ss.clear();
    ss.str(input);
    ss >> b;
    if (!ss || cin.fail() || b < 0) {
        throw std::invalid_argument("Second Fibonacci number must be a non-negative integer.");
    }

    // Prompt user for number of sequence elements to generate
    std::cout << "Enter the number of Fibonacci sequence elements to generate: ";
    std::getline(std::cin, input);
    ss.clear();
    ss.str(input);
    ss >> n;
    if (!ss || cin.fail() || n <= 0) {
        throw std::invalid_argument("Number of sequence elements must be a positive integer.");
    }

    // Generate Fibonacci sequence using recursive function
    for (int I = 0; I < n; i++) {
        unsigned long long fib = fibonacci(i, a, b);
        std::cout << fib << " ";
    }

    return 0;
}
```

