```csharp
public static decimal CalculateTotalCost(decimal carPrice, decimal clothesPrice, decimal bookPrice)
{
    // Check if car price meets the constraint
    const decimal MIN_CAR_PRICE = 2 * (clothesPrice + bookPrice);
    if (carPrice < MIN_CAR_PRICE)
    {
        // Adjust car price to meet the constraint
        decimal excess = MIN_CAR_PRICE - carPrice;
        clothesPrice += excess * clothesPrice / (clothesPrice + bookPrice);
        bookPrice += excess * bookPrice / (clothesPrice + bookPrice);
        carPrice = MIN_CAR_PRICE;
    }

    // Calculate total cost
    return carPrice + clothesPrice + bookPrice;
}

// Example usage:
Console.WriteLine(CalculateTotalCost(3000, 100, 20)); // Total cost: $3200.00
Console.WriteLine(CalculateTotalCost(2500, 100, 20)); // Total cost: $3120.00
