from django.db import models
from polymorphic.models import PolymorphicModel, PolymorphicField
from polymorphic.query import PolymorphicQuerySet

class BaseModel(PolymorphicModel):
    name = models.CharField(max_length=255)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        abstract = True

class TableA(BaseModel):
    field_a = models.IntegerField()

    def __str__(self):
        return f"Table A: {self.name}"

class TableB(BaseModel):
    field_b = models.FloatField()

    def __str__(self):
        return f"Table B: {self.name}"

class MyModelManager(models.Manager):
    def get_queryset(self):
        return PolymorphicQuerySet(self.model, self.using or default())

class MyModel(models.Model):
    objects = MyModelManager()

    def __str__(self):
        return str(self.object)

    object = PolymorphicField(parent_link=True, blank=True)

    @property
    def swapped_object(self):
        if isinstance(self.object, TableA):
            return TableB(field_b=self.object.field_a)
        elif isinstance(self.object, TableB):
            return TableA(field_a=self.object.field_b)
        else:
            raise Exception("Invalid object type")

