@RestController
@RequestMapping("/oauth")
public class OAuthController {
    @Autowired
    private OAuth2RestTemplate restTemplate;

    @GetMapping("/token")
    public String getAccessToken(@RequestParam("code") String code) {
        HttpEntity<String> entity = new HttpEntity<>(authorizationCodeServices().getAuthorizationCode(code));
        ResponseEntity<Map> response = restTemplate.postForEntity("https://example.com/oauth/token", entity, Map.class);
        return response.getBody().get("access_token").toString();
    }

    @GetMapping("/user")
