        HttpEntity<Void> entity = new HttpEntity<>(HttpHeaders.AUTHORIZATION, bearerToken);
        ResponseEntity<UserInfo> response = restTemplate.exchange("https://example.com/api/user", HttpMethod.GET, entity, UserInfo.class);
        return response.getBody();
    }
}
```

