Here's an example of simulating natural selection using MATLAB:

```matlab
% Initialize populations with different traits
populationSize = 1000;
phenotypeA = rand(1, populationSize); % Trait A with values between 0 and 1
phenotypeB = rand(1, populationSize); % Trait B with values between 0 and 1
survivalFitnessA = 0.8 * phenotypeA; % Fitness function for trait A, where 0.8 is the survival rate
survivalFitnessB = 0.9 * (1 - phenotypeB); % Fitness function for trait B, where 1-phenotypeB is the visibility factor

% Simulate generations
generations = 1000;
for generation = 1 : generations
    % Calculate total fitness for each individual
    fitness = survivalFitnessA .* survivalFitnessB;

    % Select parents based on fitness
    [~, parentIndices] = sort(fitness, 'descend');
    matingPool = parentIndices(1:2*round(0.25*populationSize),:); % Select 25% of individuals for mating

    % Generate offspring with random combinations of traits
    offspring = matingPool(1,:).*phenotypeA(matingPool(:,2),:) + matingPool(2,:).*(1-phenotypeA(matingPool(:,2),:));
    offspringFitness = survivalFitnessA .* survivalFitnessB;

    % Update populations
    populationA(1:populationSize, :) = offspring(1:populationSize, :);
    populationB(1:populationSize, :) = 1 - offspring(1:populationSize, :);
end

% Plot the change in frequency of trait A over time
figure;
subplot(2,1,1);
plot(1:generations, mean(populationA(:))/populationSize, 'r');
title('Change in Frequency of Trait A');
xlabel('Generation');
ylabel('Frequency');
subplot(2,1,2);
