#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *input_str = "";
    int i;

    // Concatenate all command-line arguments into a single string
    for (i = 0; i < argc; i++) {
        input_str = realloc(input_str, strlen(input_str) + strlen(argv[i]) + 1);
        strcat(input_str, argv[i]);
        strcat(input_str, " ");
    }

    // Remove trailing space character
    input_str[strlen(input_str) - 1] = '\0';

    printf("Converted command-line arguments: %s\n", input_str);

    return 0;
}
