```php
function getLoyalCustomers($startDate, $endDate, $productId)
{
    $sql = "SELECT DISTINCT c.id AS customer_id, c.name AS customer_name, c.email AS customer_email, c.phone AS customer_phone, SUM(p.quantity) AS total_purchases
            FROM purchases p
            JOIN customers c ON p.customer_id = c.id
            WHERE p.date BETWEEN :start_date AND :end_date AND p.product_id = :product_id
            GROUP BY c.id
            HAVING total_purchases >= 3";
    $stmt = $this->pdo->prepare($sql);
    $stmt->bindParam(':start_date', $startDate);
    $stmt->bindParam(':end_date', $endDate);
    $stmt->bindParam(':product_id', $productId);
    $stmt->execute();
    return $stmt->fetchAll();
}
```

