Here's an implementation of `RedisClient` class based on your requirements:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    // Handle errors
    this.client.on('error', (err) => {
      console.error(`Redis Client Error: ${err}`);
    });
  }

  isAlive() {
    return this.client.ping().then(() => true).catch(() => false);
  }

  get(key) {
    return this.client.get(key).then((value) => {
      if (value === null) {
        throw new Error(`Key '${key}' not found`);
      }
      return value;
    });
  }

  set(key, value, ttl) {
    return this.client.setex(key, ttl, value).then(() => {
      return value;
    });
  }

  del(key) {
    return this.client.del(key).then(() => {
      return true;
    }).catch(() => {
      throw new Error(`Key '${key}' not found`);
    });
  }
}

// Create and export an instance of RedisClient
const redisClient = new RedisClient();
module.exports = redisClient;
```

This implementation provides methods for creating a Redis client, checking if it's alive, getting values from Redis, setting values with TTL, and deleting keys. All potential errors are handled and thrown as custom errors. The `isAlive()` method is asynchronous because we can't check the connection status synchronously since it would block the thread. For more information about Redis, you can refer to its official documentation: https://redis.io/documentation

