here's an example:

```powershell
# import admodule for powershell
import-module activedirectory

# define necessary variables
$domaincontroller = "dc1.example.com"
$domainname = "example.com"
$searchpath = "c:\path\to\directory\"

# function to traverse directories recursively
function get-aclrecursive($path) {
    get-childitem $path -recurse | foreach-object {
        if ($_.psiscontainer) {
            get-aclrecursive $_.fullname
        } else {
            $acl = get-acl $_.fullname
            $result = test-sidhistory -sidlist $acl.access | select-object -expandproperty sidhistory
            $sids = @()
            foreach ($obj in $result) {
                $sids += $obj.value
            }
            $aclsid = @()
            foreach ($obj in $acl.access) {
                $aclsid += $obj.identityreference
            }
            $matching = $aclsid | where-object {$sids -contains $_}
            if ($matching.count -gt 0) {
                write-host "$($_.fullname)"
                foreach ($obj in $matching) {
                    write-host "$($obj): $($result[$sids.indexof($obj)].samaccountname)"
                }
            }
        }
    }
}

